  // `try_rfold` where that reaches the crate's own (#220), else its back.
  if (it.back !== undefined || it.tryRfold !== undefined) {
    filter.back = () => $findBack(it, p, (value) => ({ done: false, value }), drop) ?? { done: true, value: undefined };
  }
