  // exact of numbers, as it knows how many it has left, and of `n..`,
  // `{ next: $rangeFromNext }`, `usize::MAX` and none known (ADR 0918, #400).
  const ranged = iterator === undefined ? undefined : $rangeHintOf(iterator.next);
